const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dcPoint = ee.Geometry.Point([-77.0369, 38.9072]);
  const startDate = '2019-01-29';
  const endDate = '2019-02-05';

  // 2. Data Acquisition & Check
  const era5Collection = ee.ImageCollection('ECMWF/ERA5/DAILY')
    .select('mean_2m_air_temperature')
    .filterDate(startDate, endDate)
    .filterBounds(dcPoint);

  const collectionSize = era5Collection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No ERA5 images found for the period.`);
    console.log('A');
    return;
  }
  console.log(`Found ${collectionSize} daily images for the period.`);

  // 3. Processing: Find min and max temperature images over the collection
  const minTempImage = era5Collection.min();
  const maxTempImage = era5Collection.max();

  // 4. Calculation: Extract min and max values at the point
  // The scale is not critical for a single point from a global dataset like ERA5.
  const scale = 1000;
  const minTempK = minTempImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: dcPoint,
    scale: scale
  }).get('mean_2m_air_temperature');

  const maxTempK = maxTempImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: dcPoint,
    scale: scale
  }).get('mean_2m_air_temperature');

  // Server-side calculation to get results in one getInfo() call
  const results = ee.Dictionary({
    min: minTempK,
    max: maxTempK
  }).getInfo();

  // 5. Validation & Final Answer
  if (results.min === null || results.max === null) {
    console.log('Calculation failed: Could not retrieve temperature values.');
    console.log('C3');
    return;
  }

  // Convert from Kelvin to Celsius
  const minTempC = results.min - 273.15;
  const maxTempC = results.max - 273.15;
  const tempDifference = maxTempC - minTempC;

  console.log(`Min Air Temp: ${minTempC.toFixed(2)} C`);
  console.log(`Max Air Temp: ${maxTempC.toFixed(2)} C`);
  console.log(`Temperature Difference: ${tempDifference.toFixed(2)} C`);

  if (tempDifference >= 24) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
